using System;
using System.Collections.Generic;

namespace AkaiS950Synth
{
    /// <summary>
    /// Birdsong: real birds, recorded.
    ///
    /// Everything else in the library is drawn from arithmetic. These are not: they are five
    /// short calls from Simon Moscrop's own recordings, copyright-free and given to the
    /// project for this disk, kept here exactly as they were sampled - twelve-bit words at
    /// 22,050 Hz, taken off the disk he made them on. A first attempt at drawing birdsong
    /// was tried and dropped; real birds sound like birds.
    ///
    /// Only the short calls are here. A long recording was left out, as was anything over a
    /// second and a half: a call is what a key wants to play, and the S950's memory goes
    /// further with five calls than with one long take.
    ///
    /// The words are carried in this source as base64, so every build of the generator
    /// makes the same disk with no file beside it to find - on Windows, and on the Mac and
    /// Linux machines that build MzDebirth.
    ///
    /// THE PROGRAMMES. BIRDS gives each call an octave of the keyboard, from C1, playing at
    /// its own pitch on the bottom key and an octave higher at the top - the layout of the
    /// disk the calls came from. AVIARY has them on a key each from C3, at their own pitch,
    /// as a kit.
    /// </summary>
    internal static class Birds
    {
        sealed class Recorded
        {
            public readonly string Name;
            public readonly int Rate;
            public readonly string Words;      // the twelve-bit words, little-endian int16, base64

            public Recorded(string name, int rate, string words) { Name = name; Rate = rate; Words = words; }

            public short[] Decode()
            {
                var bytes = Convert.FromBase64String(Words);
                var w = new short[bytes.Length / 2];
                Buffer.BlockCopy(bytes, 0, w, 0, bytes.Length);
                return w;
            }
        }

        static readonly Recorded[] Calls =
        {
            new Recorded("BIRD_2", 22050,
                ""),
            new Recorded("BIRD_3", 22050,
                ""),
            new Recorded("BIRD_4", 22050,
                ""),
            new Recorded("BIRD_5", 22050,
                ""),
            new Recorded("BIRD_6", 22050,
                ""),
        };

        public static List<Patches.Wave> Waves()
        {
            var outp = new List<Patches.Wave>();
            for (int k = 0; k < Calls.Length; k++)
            {
                var c = Calls[k];
                outp.Add(new Patches.Wave
                {
                    Name = c.Name,
                    Rate = c.Rate,
                    Root = 36 + 12 * k,             // its own pitch on the bottom key of its octave
                    Oneshot = () => c.Decode()
                });
            }
            return outp;
        }

        public static List<Patch> Programmes()
        {
            var octaves = new List<Layer>();
            var aviary = new List<Layer>();
            for (int k = 0; k < Calls.Length; k++)
            {
                octaves.Add(new Layer { Sample = Calls[k].Name, LowKey = 36 + 12 * k, HighKey = 47 + 12 * k });
                aviary.Add(new Layer { Sample = Calls[k].Name, LowKey = 60 + k, HighKey = 60 + k });
            }

            return new List<Patch>
            {
                new Patch
                {
                    Name = "BIRDS", A = 0, D = 99, S = 99, R = 25,
                    Filter = 99, KeyToFilter = 0, VelToFilter = 0, VelToLoudness = 25,
                    OneShot = true, Layers = octaves.ToArray()
                },
                new Patch
                {
                    Name = "AVIARY", A = 0, D = 99, S = 99, R = 25,
                    Filter = 99, KeyToFilter = 0, VelToFilter = 0, VelToLoudness = 25,
                    OneShot = true, ConstantPitch = true, Layers = aviary.ToArray()
                }
            };
        }
    }
}
